<?php declare(strict_types=1);if(PHP_SAPI!=='cli')exit;require dirname(__DIR__).'/inc/db.php';require dirname(__DIR__).'/inc/env.php';$email=strtolower(trim((string)env_value('BOOTSTRAP_ADMIN_EMAIL','')));if(!filter_var($email,FILTER_VALIDATE_EMAIL)){fwrite(STDERR,"Set BOOTSTRAP_ADMIN_EMAIL first.\n");exit(1);}$a=$pdo->query("SELECT * FROM admins WHERE role='admin' ORDER BY id LIMIT 1")->fetch();if(!$a){fwrite(STDERR,"No legacy administrator found.\n");exit(1);}$q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);$uid=$q->fetchColumn();if(!$uid){$pdo->prepare("INSERT INTO users(name,email,password_hash,role,is_active) VALUES(?,?,?,'admin',1)")->execute([$a['username'],$email,$a['password']]);$uid=$pdo->lastInsertId();}$pdo->prepare('UPDATE admins SET user_id=? WHERE id=?')->execute([$uid,$a['id']]);echo "Bootstrap administrator linked.\n";
